window.FILM_WORK_PROMPTS={"work_id":"src-887491db1b6e1b88","records":[{"work_id":"src-887491db1b6e1b88","frame_id":"FG-cdaf492d8d354541","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (891).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"画面主体为一张倒置的人脸，面部布满红色液体痕迹，背景右侧可见大量金色褶皱反光材质，人物头部占据画面绝大部分空间。","analysis":"构图极度紧凑，人物面部倒置占据画面左侧及中央，右侧背景为金色褶皱物体。可见范围仅限头部及少许颈部，无全身或肢体动作。光线柔和，皮肤呈现红润色泽，与鲜红液体及金色背景形成色彩层次，无强烈阴影。","prompt":"倒置的人脸特写，面部皮肤红润，鼻孔与嘴角周围流淌着鲜红色液体，液体顺着脸颊向下延伸。人物双眼紧闭，金色卷发散落在头部两侧。画面右侧背景填充着金色褶皱反光材质，呈现出类似金属箔或织物的质感，表面有细碎的高光反射。整体色调偏暖，红色液体与金色背景形成视觉对比，画面充满压抑与不安的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:21:52-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (891).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.497,"observed_resolution":"normal","observation_limits":[],"id":"VP-af2311a5acb9ab9b","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-90a3dcda8bbb1ff3","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (911).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"户外沙地场景，右侧一棵枝叶茂密的大树，树下及周围散落着多名赤裸上身的人物，有的躺卧有的倚靠，左后方站立一人，地面有木凳和散落的衣物。","analysis":"画面采用高角度俯视拍摄，环境占据大部分空间，沙地纹理清晰。右侧大树形成视觉重心，树冠遮蔽部分光线，树下形成阴影区。人物多呈躺卧或半坐姿态，身体大部分可见，衣着极少，仅见红色、蓝色等色块衣物。左后方站立人物全身可见，身形较小。整体光线明亮，色彩偏暖黄，对比度适中，阴影柔和。","prompt":"高角度俯视的户外沙地场景，右侧一棵枝叶繁茂的大树占据画面右半部分，树干粗壮，树冠投下阴影。树下及周围沙地上散落着多名赤裸上身的人物，前景左侧一人俯卧，中间一人侧卧，右侧一人半躺，树下有人倚靠树干，还有一人蜷缩坐着。左后方远处站立一名全身可见的人物，旁边有一个小木凳。地面散落着红色、蓝色等衣物色块。沙地呈浅黄褐色，背景远处有稀疏的绿色植被。光线明亮，整体色调偏暖，阴影柔和，人物皮肤呈现日晒后的色泽。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:22:00-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (911).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.525,"observed_resolution":"normal","observation_limits":[],"id":"VP-40037c282b507511","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-d24594e82dafb940","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (908).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"两名男子在崎岖的岩石荒地上，左侧男子赤裸上身跪坐，右侧男子身着深色古装站立，两人身体靠近，背景为连绵的灰色乱石。","analysis":"画面采用平视视角，构图紧凑。左侧人物呈跪姿，全身可见，肌肉线条清晰；右侧人物站立，占据画面右侧较大比例，身着深色长袍与金属护具。光线为强烈的自然日光，在岩石和人物皮肤上形成高对比度的明暗层次，色彩以岩石的灰白和衣物的深黑为主。","prompt":"在阳光强烈的崎岖岩石荒地上，两名男子近距离互动。左侧男子赤裸上身，仅穿浅色腰布，呈跪姿，身体前倾，双手伸向右侧人物。右侧男子站立，金发，身穿黑色长袍，肩部有带金属圆钉的护具，手臂佩戴宽手镯，身体略微后仰。背景是层层叠叠的灰色乱石，天空呈淡白色。强烈的直射光在人物皮肤和岩石表面投下清晰的阴影，画面质感粗粝，色彩对比鲜明。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:22:08-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (908).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.494,"observed_resolution":"normal","observation_limits":[],"id":"VP-a0591b909d4ce639","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-a3379260f427f17a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (890).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"一名赤裸上身的男子低头注视胸前，双手在胸口位置握持着某种深色物体，背景为斑驳粗糙的暗色墙面，环境昏暗压抑。","analysis":"画面截取人物上半身，头部至胸部区域占据画面主体，右侧留有大面积斑驳墙面。人物呈低头俯视姿态，双手在胸前交握。光线从上方投射，在额头、鼻梁、锁骨及手臂肌肉上形成高光，与周围深暗背景形成强烈明暗对比，整体色调偏冷且带有颗粒感。","prompt":"一名年轻男子赤裸上身，黑色短发，低头向下注视，神情专注。他双手在胸前握持着一个深色物体，手臂肌肉线条清晰，皮肤表面带有光泽。背景是粗糙斑驳的暗色墙面，右侧墙面有明显的剥落纹理。光线从上方投射，照亮人物的额头、鼻梁、锁骨和手臂，形成强烈的明暗对比，整体色调偏冷，画面带有明显的胶片颗粒感，氛围压抑。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:22:15-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (890).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.493,"observed_resolution":"normal","observation_limits":[],"id":"VP-c6698df54626d603","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-ba8a49c78513ace9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (812).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"在布满碎石的山脊上，多名人物分散站立或蹲坐。部分人物手持长弓，一人背对镜头站立，右侧有一根竖立的木杆，背景是连绵的山脉和灰白天空。","analysis":"画面采用远景构图，人物在画面中占比极小，环境占据主导。视角平视，光线为均匀的漫射光，缺乏强烈的明暗对比。色彩呈现低饱和度的复古胶片质感，天空与远山呈灰蓝色，地面为土黄色碎石，人物衣着颜色各异，包括深色、红色和浅色。","prompt":"这是一张远景视角的户外静帧，画面展现了荒凉的山脊地貌，地面铺满了灰白色的碎石和乱石。多名人物分散站立在画面中景位置，身形在广阔的环境中显得渺小。左侧一人蹲坐，旁边一人站立手持长弓；中间一人站立持弓，另一人背对镜头站立，身穿深色衣物；右侧有一根竖立的木杆，旁边有人影，最右侧一人站立持弓。背景是层叠的远山，天空呈现灰白色，光线柔和均匀，整体色调偏冷且饱和度低，具有复古胶片质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:22:23-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (812).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.482,"observed_resolution":"normal","observation_limits":[],"id":"VP-911ca3a90b6258cc","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-59686e5693752a0d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (891).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"一名留着络腮胡的男子面部特写，鼻梁上佩戴着金属质地的长鼻装置，身穿深色毛皮衣物。背景昏暗，左侧可见模糊的花卉图案，右侧有金色反光物体及红色花朵。","analysis":"画面采用极近景构图，人物面部占据画面中心及大部分区域，视觉重心集中在其佩戴的长鼻面具上。人物头部略微向左侧偏转，眼神直视前方。光线从右上方投射，在额头、鼻梁及面具上形成强烈高光，面部左侧及颈部处于阴影中，明暗对比强烈。背景虚化，色彩层次包含左侧的暗红与绿色，以及右侧的金色与暗紫色，衬托出主体。","prompt":"一名留着深色络腮胡的成年男子面部特写，他双眼圆睁，嘴巴微张，神情显得惊讶或正在说话。最显著的特征是其鼻梁上佩戴着一个黄铜色的长鼻面具，面具通过细金属带固定在脸颊两侧。男子身穿深色毛皮质感的厚重衣物，领口敞开。背景处于焦外虚化状态，左侧隐约可见深绿色叶片与红色花朵的图案，右侧背景有模糊的金色雕塑或装饰物，以及几朵清晰的红色玫瑰。光线从右上方打入，照亮了男子的额头、面具和右脸颊，形成强烈的明暗对比，营造出一种戏剧化的舞台光效。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T16:16:44+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (891).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.52,"observed_resolution":"normal","observation_limits":[],"id":"VP-6323300a87a622f3","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-2fa77ddfc1358f97","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (911).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"画面主体为一只人手，食指指尖停驻着一只微小的淡黄色蜘蛛。背景是大面积深绿色的模糊色块，光线柔和，营造出一种静谧且微观的视觉氛围。","analysis":"构图采用极近距离拍摄，焦点清晰地落在指尖的蜘蛛与指甲上，背景完全虚化。人物仅可见手指部分，食指竖直向上，中指与无名指在下方横向延伸，形成稳定的支撑结构。蜘蛛相对于指尖显得极小，突显了微观视角。光线从上方或侧方照射，使皮肤呈现自然的粉润色泽，与深暗的背景形成强烈的明暗对比。","prompt":"一张极近距离的微距摄影画面，焦点集中在一只人手的手指上。食指竖直向上，指尖上停着一只极小的淡黄色蜘蛛，蜘蛛的细腿清晰可见。手指皮肤纹理细腻，指甲修剪整齐，呈现自然的粉白色。下方有另外两根手指横向延伸，处于略微失焦的状态。背景是大面积深绿色的模糊色块，没有任何具体细节，营造出深邃的空间感。光线柔和自然，照亮了手指和蜘蛛，使主体从暗色背景中突显出来，整体色调偏暖，具有胶片摄影的质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T16:16:51+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (911).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.498,"observed_resolution":"normal","observation_limits":[],"id":"VP-43c2331f984c3b01","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-120fb03db37c5847","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (908).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"四名人物散布在灰白色碎石滩上，背景是占据画面大半的陡峭岩石山坡，坡面散布着稀疏的绿色灌木丛。","analysis":"画面采用广角视野，背景山体占据约70%的垂直空间，形成巨大的压迫感。前景人物全身可见，因距离镜头远近不同呈现明显的大小差异，左侧人物相对较大，右侧人物呈奔跑姿态。光线为强烈的自然日光，岩石表面纹理清晰，明暗对比强烈，色彩以灰褐、土黄与暗绿为主。","prompt":"这是一张户外广角摄影作品，背景是一座巨大的、布满碎石和稀疏绿色植被的陡峭山坡，岩石纹理粗糙，占据画面大部分面积。前景是一片平坦的灰白色碎石滩，四名人物散布其间。左侧一名身穿橙红色衣物的人物站立，面向右侧；中间一名身穿浅色衣物的人物站立；右侧一名赤裸上身的人物站立；最右侧一名身穿橙红色衣物的人物呈奔跑姿态。人物在巨大的山体背景下显得渺小，光线明亮，色彩呈现自然的土黄与灰褐色调，具有胶片质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T16:16:59+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (908).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.508,"observed_resolution":"normal","observation_limits":[],"id":"VP-b92ea31a589a5a9a","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-14deec2922edae63","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (883).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"画面主体为巨大的米黄色石砌废墟墙体，占据大部分空间。左下方一名赤膊人物坐在石堆上，右上方一名穿白衣短裙的人物站在高处，背景可见绿色山丘与蓝色水面。","analysis":"构图利用废墟墙体形成框架，将视线引向背景。左下人物呈坐姿，全身可见，身体蜷缩，头部低垂；右上人物呈站立姿态，双臂平举，全身可见，因距离较远显得较小。光线为强烈的自然日光，石墙表面粗糙，明暗对比明显，色彩以暖黄色调为主，背景带有冷色调的蓝绿。","prompt":"这是一张高饱和度的户外静帧，画面被巨大的米黄色石砌废墟墙体占据，墙体由不规则石块堆砌，表面粗糙且带有风化痕迹。左下方，一名赤膊人物坐在石堆上，身披淡紫色布料，双腿弯曲，头部低垂，姿态蜷缩。右上方，一名身穿白色无袖上衣和花纹短裙的人物站在高处，双臂向两侧平举，身体舒展。背景透过墙体缺口可见远处的绿色山丘和一小片蓝色水面，远处山脊上隐约可见一座方形建筑。强烈的自然光照射在石墙上，形成鲜明的明暗对比，整体色调偏暖，呈现出一种炎热、干燥的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T16:17:08+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (883).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.519,"observed_resolution":"normal","observation_limits":[],"id":"VP-3b3d5176f2a158ed","origin":"visual"},{"work_id":"src-887491db1b6e1b88","frame_id":"FG-a310f54af73fa925","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (803).jpg","source_page":"https://film-grab.com/2015/12/14/sebastiane/","scene":"在荒凉的山脊岩石地面上，几名身着古代服饰的人物散布。右侧一人被绑在竖立的木桩上，周围有站立和蹲坐的武装人员，背景是连绵的远山和蓝天。","analysis":"画面采用广角视野，环境占比极大，天空与远山占据画面上半部。人物在画面中显得较小，呈散点分布。右侧竖立的木桩是显著的垂直视觉元素。光线为强烈的自然日光，色彩以天空的蓝、地面的灰白和人物衣着的红褐为主，对比鲜明。","prompt":"这是一张户外广角摄影画面，背景是连绵起伏的灰绿色山峦和纯净的蓝色天空。前景是布满碎石和干草的灰白色岩石地面。画面中散布着数名身着古代风格服饰的人物。左侧前景站立着一名身穿红褐色皮甲、头戴金属头盔的人物，背对镜头。右侧竖立着一根粗糙的木桩，一名赤裸上身的人物被绑在上面，双臂上举。木桩周围有蹲坐和站立的人物，其中一人身穿深色衣物。画面中央远处还有一名蹲坐的武装人员。整体光线明亮，呈现出强烈的日光照射效果，色彩以冷色调的天空和暖色调的人物服饰形成对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T16:17:16+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (803).jpg","observed_dimensions":[870,576],"source_thumbnail_dimensions":[500,331],"source_image_match_mae":0.505,"observed_resolution":"normal","observation_limits":[],"id":"VP-95a6da21f68fdf10","origin":"visual"}]};